module hipfort_rocsparse
  use hipfort_rocsparse_enums
  use hipfort_rocsparse_types
  use hipfort_handles
  use, intrinsic :: iso_c_binding
  implicit none

  interface

    !---------------------------------------------
    ! rocsparse_get_status_name
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Return the string representation of a rocSPARSE status code enum name.
    !>
    !> \details
    !> \p rocsparse_get_status_name takes a rocSPARSE status as input and returns the string
    !> representation of this status.
    !> If the status is not recognized, the function returns "Unrecognized status code".
    !>
    !> @param[in]
    !> status  a rocSPARSE status.
    !>
    !> \retval pointer to null-terminated string.
    function rocsparse_get_status_name(status) &
       result(get_status_name) &
       bind(C, name="rocsparse_get_status_name")
       import :: c_int, c_char
       integer(c_int), value :: status
       character(c_char) :: get_status_name
    end function rocsparse_get_status_name

    !---------------------------------------------
    ! rocsparse_get_status_description
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Return the rocSPARSE status code description as a string.
    !>
    !> \details
    !> \p rocsparse_get_status_description takes a rocSPARSE status as input and returns the status
    !> description as a string.
    !> If the status is not recognized, the function returns "Unrecognized status code"
    !>
    !> @param[in]
    !> status  a rocSPARSE status.
    !>
    !> \retval pointer to null-terminated string.
    function rocsparse_get_status_description(status) &
       result(get_status_description) &
       bind(C, name="rocsparse_get_status_description")
       import :: c_int, c_char
       integer(c_int), value :: status
       character(c_char) :: get_status_description
    end function rocsparse_get_status_description

    !---------------------------------------------
    ! rocsparse_enable_debug_kernel_launch
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Enable debug kernel launch.
    !> \details If the debug kernel launch is enabled, then HIP errors are checked before and
    !> after every kernel launch.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_KERNEL_LAUNCH.
    subroutine rocsparse_enable_debug_kernel_launch() &
       bind(C, name="rocsparse_enable_debug_kernel_launch")
    end subroutine rocsparse_enable_debug_kernel_launch

    !---------------------------------------------
    ! rocsparse_disable_debug_kernel_launch
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Disable debug kernel launch.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_KERNEL_LAUNCH.
    subroutine rocsparse_disable_debug_kernel_launch() &
       bind(C, name="rocsparse_disable_debug_kernel_launch")
    end subroutine rocsparse_disable_debug_kernel_launch

    !---------------------------------------------
    ! rocsparse_state_debug_kernel_launch
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Query whether debugging for kernel launch has been enabled. See \ref
    !> rocsparse_enable_debug_kernel_launch.
    !> \return 1 if enabled, 0 otherwise.
    function rocsparse_state_debug_kernel_launch() &
       result(state_debug_kernel_launch) &
       bind(C, name="rocsparse_state_debug_kernel_launch")
       import :: c_int
       integer(c_int) :: state_debug_kernel_launch
    end function rocsparse_state_debug_kernel_launch

    !---------------------------------------------
    ! rocsparse_enable_debug_arguments
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Enable debug arguments.
    !> \details If the debug arguments is enabled, then messages are displayed when errors occur
    !> during argument checking.
    !> It provides information to the user depending on the verbosity setup for
    !> \ref rocsparse_enable_debug_arguments_verbose, \ref
    !> rocsparse_disable_debug_arguments_verbose, and \ref rocsparse_state_debug_arguments_verbose.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_ARGUMENTS.
    !> \note This routine enables debug arguments verbose with \ref
    !> rocsparse_enable_debug_arguments_verbose.
    subroutine rocsparse_enable_debug_arguments() &
       bind(C, name="rocsparse_enable_debug_arguments")
    end subroutine rocsparse_enable_debug_arguments

    !---------------------------------------------
    ! rocsparse_disable_debug_arguments
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Disable debug arguments.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_ARGUMENTS.
    !> \note This routine disables debug arguments.
    subroutine rocsparse_disable_debug_arguments() &
       bind(C, name="rocsparse_disable_debug_arguments")
    end subroutine rocsparse_disable_debug_arguments

    !---------------------------------------------
    ! rocsparse_state_debug_arguments
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Query whether debugging arguments have been enabled. See \ref
    !> rocsparse_enable_debug_arguments.
    !> \return 1 if enabled, 0 otherwise.
    function rocsparse_state_debug_arguments() &
       result(state_debug_arguments) &
       bind(C, name="rocsparse_state_debug_arguments")
       import :: c_int
       integer(c_int) :: state_debug_arguments
    end function rocsparse_state_debug_arguments

    !---------------------------------------------
    ! rocsparse_enable_debug_arguments_verbose
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Enable debug arguments verbose.
    !> \details If the debug arguments (verbose) is enabled, then messages are displayed when errors
    !> occur during argument checking.
    !> It provides information to the user depending on the verbosity setup.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_ARGUMENTS_VERBOSE.
    subroutine rocsparse_enable_debug_arguments_verbose() &
       bind(C, name="rocsparse_enable_debug_arguments_verbose")
    end subroutine rocsparse_enable_debug_arguments_verbose

    !---------------------------------------------
    ! rocsparse_disable_debug_arguments_verbose
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Disable debug arguments verbose mode.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_ARGUMENTS_VERBOSE.
    subroutine rocsparse_disable_debug_arguments_verbose() &
       bind(C, name="rocsparse_disable_debug_arguments_verbose")
    end subroutine rocsparse_disable_debug_arguments_verbose

    !---------------------------------------------
    ! rocsparse_state_debug_arguments_verbose
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Query whether debugging arguments in verbose mode has been enabled. See \ref
    !> rocsparse_enable_debug_arguments_verbose.
    !> \return 1 if enabled, 0 otherwise.
    function rocsparse_state_debug_arguments_verbose() &
       result(state_debug_arguments_verbose) &
       bind(C, name="rocsparse_state_debug_arguments_verbose")
       import :: c_int
       integer(c_int) :: state_debug_arguments_verbose
    end function rocsparse_state_debug_arguments_verbose

    !---------------------------------------------
    ! rocsparse_enable_debug
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Enable debug.
    !> \details If the debug is enabled, then code traces are generated when unsuccessful status
    !> returns occur. It provides information to the user depending on the verbosity setup
    !> (\ref rocsparse_enable_debug_verbose, \ref rocsparse_disable_debug_verbose, and \ref
    !> rocsparse_state_debug_verbose).
    !> \note This routine ignores the environment variable ROCSPARSE_DEBUG.
    !> \note \ref rocsparse_enable_debug_verbose and \ref rocsparse_enable_debug_arguments are
    !> called.
    subroutine rocsparse_enable_debug() &
       bind(C, name="rocsparse_enable_debug")
    end subroutine rocsparse_enable_debug

    !---------------------------------------------
    ! rocsparse_disable_debug
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Disable debug.
    !> \note This routine disables debug arguments with \ref rocsparse_disable_debug_arguments.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG.
    subroutine rocsparse_disable_debug() &
       bind(C, name="rocsparse_disable_debug")
    end subroutine rocsparse_disable_debug

    !---------------------------------------------
    ! rocsparse_state_debug
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Query whether debug has been enabled. See \ref rocsparse_enable_debug.
    !> \return 1 if enabled, 0 otherwise.
    function rocsparse_state_debug() &
       result(state_debug) &
       bind(C, name="rocsparse_state_debug")
       import :: c_int
       integer(c_int) :: state_debug
    end function rocsparse_state_debug

    !---------------------------------------------
    ! rocsparse_enable_debug_warnings
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Enable debug warnings
    !> \details When the debug warnings are enabled, some specific warnings are printed during
    !> execution.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_WARNINGS.
    subroutine rocsparse_enable_debug_warnings() &
       bind(C, name="rocsparse_enable_debug_warnings")
    end subroutine rocsparse_enable_debug_warnings

    !---------------------------------------------
    ! rocsparse_disable_debug_warnings
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Disable debug warnings
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_WARNINGS.
    subroutine rocsparse_disable_debug_warnings() &
       bind(C, name="rocsparse_disable_debug_warnings")
    end subroutine rocsparse_disable_debug_warnings

    !---------------------------------------------
    ! rocsparse_enable_debug_verbose
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Enable debug verbose.
    !> \details Debug in verbose mode displays a stack of code traces showing where the code handles
    !> an unsuccessful status.
    !> \note This routine enables debug arguments in verbose mode with \ref
    !> rocsparse_enable_debug_arguments_verbose.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_VERBOSE.
    subroutine rocsparse_enable_debug_verbose() &
       bind(C, name="rocsparse_enable_debug_verbose")
    end subroutine rocsparse_enable_debug_verbose

    !---------------------------------------------
    ! rocsparse_disable_debug_verbose
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Disable debug verbose.
    !> \note This routine disables debug arguments verbose with \ref
    !> rocsparse_disable_debug_arguments.
    !> \note This routine ignores the environment variable \p ROCSPARSE_DEBUG_VERBOSE.
    subroutine rocsparse_disable_debug_verbose() &
       bind(C, name="rocsparse_disable_debug_verbose")
    end subroutine rocsparse_disable_debug_verbose

    !---------------------------------------------
    ! rocsparse_state_debug_verbose
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Query whether debug has been enabled in verbose mode. See \ref
    !> rocsparse_enable_debug_verbose.
    !> \return 1 if enabled, 0 otherwise.
    function rocsparse_state_debug_verbose() &
       result(state_debug_verbose) &
       bind(C, name="rocsparse_state_debug_verbose")
       import :: c_int
       integer(c_int) :: state_debug_verbose
    end function rocsparse_state_debug_verbose

    !---------------------------------------------
    ! rocsparse_enable_debug_force_host_assert
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Enable debug to force host asserts.
    !> \details Debug for force host assert forces the evaluation of asserts on the host when the
    !> compiler directive \p NDEBUG is used.
    subroutine rocsparse_enable_debug_force_host_assert() &
       bind(C, name="rocsparse_enable_debug_force_host_assert")
    end subroutine rocsparse_enable_debug_force_host_assert

    !---------------------------------------------
    ! rocsparse_disable_debug_force_host_assert
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Disable debug to force host asserts.
    subroutine rocsparse_disable_debug_force_host_assert() &
       bind(C, name="rocsparse_disable_debug_force_host_assert")
    end subroutine rocsparse_disable_debug_force_host_assert

    !---------------------------------------------
    ! rocsparse_state_debug_force_host_assert
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Query whether the debug command to force host asserts has been enabled. See \ref
    !> rocsparse_enable_debug_force_host_assert.
    !> \return 1 if enabled, 0 otherwise.
    function rocsparse_state_debug_force_host_assert() &
       result(state_debug_force_host_assert) &
       bind(C, name="rocsparse_state_debug_force_host_assert")
       import :: c_int
       integer(c_int) :: state_debug_force_host_assert
    end function rocsparse_state_debug_force_host_assert

    !---------------------------------------------
    ! rocsparse_enable_roctx
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Enable rocTX instrumentation.
    !> \note This routine ignores the environment variable \p ROCSPARSE_ROCTX.
    subroutine rocsparse_enable_roctx() &
       bind(C, name="rocsparse_enable_roctx")
    end subroutine rocsparse_enable_roctx

    !---------------------------------------------
    ! rocsparse_disable_roctx
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Disable rocTX instrumentation.
    !> \note This routine ignores the environment variable \p ROCSPARSE_ROCTX.
    subroutine rocsparse_disable_roctx() &
       bind(C, name="rocsparse_disable_roctx")
    end subroutine rocsparse_disable_roctx

    !---------------------------------------------
    ! rocsparse_state_roctx
    !---------------------------------------------
    !> \ingroup aux_module
    !> \details Query whether rocTX instrumentation has been enabled. See \ref
    !> rocsparse_enable_roctx.
    !> \return 1 if enabled, 0 otherwise.
    function rocsparse_state_roctx() &
       result(state_roctx) &
       bind(C, name="rocsparse_state_roctx")
       import :: c_int
       integer(c_int) :: state_roctx
    end function rocsparse_state_roctx

  end interface

  interface rocsparse_create_handle
    !---------------------------------------------
    ! rocsparse_create_handle
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Create a rocSPARSE handle.
    !>
    !> \details
    !> \p rocsparse_create_handle creates the rocSPARSE library context. It must be
    !> initialized before any other rocSPARSE API function is invoked and must be passed to
    !> all subsequent library function calls. The handle should be destroyed at the end
    !> using rocsparse_destroy_handle().
    !>
    !> @param[out]
    !> handle  the pointer to the handle to the rocSPARSE library context.
    !>
    !> \retval rocsparse_status_success the initialization succeeded.
    !> \retval rocsparse_status_invalid_handle \p handle pointer is invalid.
    !> \retval rocsparse_status_internal_error an internal error occurred.
    function rocsparse_create_handle_raw(handle) &
       result(create_handle_raw) &
       bind(C, name="rocsparse_create_handle")
       import :: c_ptr, c_int
       type(c_ptr) :: handle
       integer(c_int) :: create_handle_raw
    end function rocsparse_create_handle_raw

    module procedure rocsparse_create_handle_typed
  end interface rocsparse_create_handle

  interface rocsparse_destroy_handle
    !---------------------------------------------
    ! rocsparse_destroy_handle
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Destroy a rocSPARSE handle.
    !>
    !> \details
    !> \p rocsparse_destroy_handle destroys the rocSPARSE library context and releases all
    !> resources used by the rocSPARSE library.
    !>
    !> @param[in]
    !> handle  the handle to the rocSPARSE library context.
    !>
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_invalid_handle \p handle is invalid.
    !> \retval rocsparse_status_internal_error an internal error occurred.
    function rocsparse_destroy_handle_raw(handle) &
       result(destroy_handle_raw) &
       bind(C, name="rocsparse_destroy_handle")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int) :: destroy_handle_raw
    end function rocsparse_destroy_handle_raw

    module procedure rocsparse_destroy_handle_typed
  end interface rocsparse_destroy_handle

  interface rocsparse_destroy_error
    !---------------------------------------------
    ! rocsparse_destroy_error
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Destroy a rocSPARSE error descriptor.
    !>
    !> \details
    !> \p rocsparse_destroy_error destroys the rocSPARSE error descriptor.
    !>
    !> @param[in]
    !> error  the pointer to the rocSPARSE error descriptor, which can be a null pointer.
    !>
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_internal_error an internal error occurred.
    function rocsparse_destroy_error_raw(error) &
       result(destroy_error_raw) &
       bind(C, name="rocsparse_destroy_error")
       import :: c_ptr, c_int
       type(c_ptr), value :: error
       integer(c_int) :: destroy_error_raw
    end function rocsparse_destroy_error_raw

    module procedure rocsparse_destroy_error_typed
  end interface rocsparse_destroy_error

  interface rocsparse_error_get_message
    !---------------------------------------------
    ! rocsparse_error_get_message
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Error message from a rocSPARSE error descriptor.
    !>
    !> \details
    !> \p rocsparse_error_message returns a C-style string that provides details for the error.
    !>
    !> @param[in]
    !> error  the error to the rocSPARSE error descriptor.
    !>
    !> @return an error message from a rocSPARSE error descriptor.
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_internal_error an internal error occurred.
    function rocsparse_error_get_message_raw(error) &
       result(error_get_message_raw) &
       bind(C, name="rocsparse_error_get_message")
       import :: c_ptr, c_char
       type(c_ptr), value :: error
       character(c_char) :: error_get_message_raw
    end function rocsparse_error_get_message_raw

    module procedure rocsparse_error_get_message_typed
  end interface rocsparse_error_get_message

  interface rocsparse_set_stream
    !---------------------------------------------
    ! rocsparse_set_stream
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Specify user-defined HIP stream.
    !>
    !> \details
    !> \p rocsparse_set_stream specifies the stream to be used by the rocSPARSE library
    !> context and all subsequent function calls.
    !>
    !> @param[inout]
    !> handle  the handle to the rocSPARSE library context.
    !> @param[in]
    !> stream  the stream to be used by the rocSPARSE library context.
    !>
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_invalid_handle \p handle is invalid.
    !>
    !> \par Example
    !> This example illustrates how a user-defined stream can be used in rocSPARSE.
    !> \code{.c}
    !> // Create rocSPARSE handle
    !> rocsparse_handle handle;
    !> rocsparse_create_handle(&handle);
    !>
    !> // Create stream
    !> hipStream_t stream;
    !> hipStreamCreate(&stream);
    !>
    !> // Set stream to rocSPARSE handle
    !> rocsparse_set_stream(handle, stream);
    !>
    !> // Do some work
    !> // ...
    !>
    !> // Clean up
    !> rocsparse_destroy_handle(handle);
    !> hipStreamDestroy(stream);
    !> \endcode
    function rocsparse_set_stream_raw(handle, stream) &
       result(set_stream_raw) &
       bind(C, name="rocsparse_set_stream")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       type(c_ptr), value :: stream
       integer(c_int) :: set_stream_raw
    end function rocsparse_set_stream_raw

    module procedure rocsparse_set_stream_typed
  end interface rocsparse_set_stream

  interface rocsparse_get_stream
    !---------------------------------------------
    ! rocsparse_get_stream
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Get the current stream from the library context.
    !>
    !> \details
    !> \p rocsparse_get_stream gets the rocSPARSE library context stream which will
    !> be used for all subsequent function calls.
    !>
    !> @param[in]
    !> handle the handle to the rocSPARSE library context.
    !> @param[out]
    !> stream the stream currently used by the rocSPARSE library context.
    !>
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_invalid_handle \p handle is invalid.
    function rocsparse_get_stream_raw(handle, stream) &
       result(get_stream_raw) &
       bind(C, name="rocsparse_get_stream")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       type(c_ptr) :: stream
       integer(c_int) :: get_stream_raw
    end function rocsparse_get_stream_raw

    module procedure rocsparse_get_stream_typed
  end interface rocsparse_get_stream

  interface rocsparse_set_pointer_mode
    !---------------------------------------------
    ! rocsparse_set_pointer_mode
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Specify the pointer mode.
    !>
    !> \details
    !> \p rocsparse_set_pointer_mode specifies the pointer mode to be used by the rocSPARSE
    !> library context and all subsequent function calls. For example, many rocSPARSE routines take
    !> \f$\alpha\f$ and \f$\beta\f$ pointers as parameters. These can be either host memory pointers
    !> or device memory pointers, depending on what the pointer mode is set to. By default, all
    !> values are passed
    !> using host pointer mode. Valid pointer modes are \ref rocsparse_pointer_mode_host
    !> or \ref rocsparse_pointer_mode_device.
    !>
    !> @param[in]
    !> handle          the handle to the rocSPARSE library context.
    !> @param[in]
    !> pointer_mode    the pointer mode to be used by the rocSPARSE library context.
    !>
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_invalid_handle \p handle is invalid.
    function rocsparse_set_pointer_mode_raw(handle, pointer_mode) &
       result(set_pointer_mode_raw) &
       bind(C, name="rocsparse_set_pointer_mode")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: pointer_mode
       integer(c_int) :: set_pointer_mode_raw
    end function rocsparse_set_pointer_mode_raw

    module procedure rocsparse_set_pointer_mode_typed
  end interface rocsparse_set_pointer_mode

  interface rocsparse_get_pointer_mode
    !---------------------------------------------
    ! rocsparse_get_pointer_mode
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Get the current pointer mode from the library context.
    !>
    !> \details
    !> \p rocsparse_get_pointer_mode gets the rocSPARSE library context pointer mode which
    !> will be used for all subsequent function calls.
    !>
    !> @param[in]
    !> handle          the handle to the rocSPARSE library context.
    !> @param[out]
    !> pointer_mode    the pointer mode that is currently used by the rocSPARSE library
    !> context.
    !>
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_invalid_handle \p handle is invalid.
    function rocsparse_get_pointer_mode_raw(handle, pointer_mode) &
       result(get_pointer_mode_raw) &
       bind(C, name="rocsparse_get_pointer_mode")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       type(c_ptr), value :: pointer_mode
       integer(c_int) :: get_pointer_mode_raw
    end function rocsparse_get_pointer_mode_raw

    module procedure rocsparse_get_pointer_mode_native
    module procedure rocsparse_get_pointer_mode_typed
  end interface rocsparse_get_pointer_mode

  interface rocsparse_get_version
    !---------------------------------------------
    ! rocsparse_get_version
    !---------------------------------------------
    !> \ingroup aux_module
    !> \brief Get rocSPARSE version
    !>
    !> \details
