    !> \retval     rocsparse_status_invalid_handle the library context was not initialized.
    !> \retval     rocsparse_status_invalid_size \p m, \p n, or \p ld is invalid.
    !> \retval rocsparse_status_invalid_pointer \p A, \p nnz_per_columns, \p csc_val, \p
    !> csc_col_ptr, or \p csc_row_ind
    !> pointer is invalid.
    !>
    !> \par Example
    function rocsparse_sdense2csc_raw(handle, m, n, descr, A, ld, nnz_per_columns, csc_val, &
                                      csc_col_ptr, csc_row_ind) &
       result(sdense2csc_raw) &
       bind(C, name="rocsparse_sdense2csc")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: m
       integer(c_int), value :: n
       type(c_ptr), value :: descr
       type(c_ptr), value :: A
       integer(c_int), value :: ld
       type(c_ptr), value :: nnz_per_columns
       type(c_ptr), value :: csc_val
       type(c_ptr), value :: csc_col_ptr
       type(c_ptr), value :: csc_row_ind
       integer(c_int) :: sdense2csc_raw
    end function rocsparse_sdense2csc_raw

