       bind(C, name="rocsparse_sdense2csr")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: m
       integer(c_int), value :: n
       type(c_ptr), value :: descr
       type(c_ptr), value :: A
       integer(c_int), value :: ld
       type(c_ptr), value :: nnz_per_rows
       type(c_ptr), value :: csr_val
       type(c_ptr), value :: csr_row_ptr
       type(c_ptr), value :: csr_col_ind
       integer(c_int) :: sdense2csr_raw
    end function rocsparse_sdense2csr_raw

    module procedure rocsparse_sdense2csr_native
    module procedure rocsparse_sdense2csr_typed
  end interface rocsparse_sdense2csr

