    !> source       source sparse matrix descriptor.
    !> @param[in]
    !> target       target sparse matrix descriptor.
    !> @param[in]
    !> stage        stage of the sparse_to_sparse computation.
    !> @param[out]
    !> buffer_size_in_bytes  size in bytes of the \p buffer
    !>
    !> \note
    !> This routine does not support batched computation.
    !>
    !> \retval      rocsparse_status_success the operation completed successfully.
    !> \retval      rocsparse_status_invalid_handle the library context was not initialized.
    !> \retval      rocsparse_status_invalid_value if any required enumeration is invalid.
    !> \retval      rocsparse_status_invalid_pointer \p mat_A, \p mat_B, or \p buffer_size_in_bytes
    !> pointer is invalid.
    function rocsparse_sparse_to_sparse_buffer_size_raw(handle, descr, source, target, stage, &
                                                        buffer_size_in_bytes) &
       result(sparse_to_sparse_buffer_size_raw) &
       bind(C, name="rocsparse_sparse_to_sparse_buffer_size")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       type(c_ptr), value :: descr
       type(c_ptr), value :: source
       type(c_ptr), value :: target
       integer(c_int), value :: stage
       type(c_ptr), value :: buffer_size_in_bytes
       integer(c_int) :: sparse_to_sparse_buffer_size_raw
    end function rocsparse_sparse_to_sparse_buffer_size_raw

    module procedure rocsparse_sparse_to_sparse_buffer_size_typed
  end interface rocsparse_sparse_to_sparse_buffer_size

  interface rocsparse_sparse_to_sparse
    !---------------------------------------------
    ! rocsparse_sparse_to_sparse
    !---------------------------------------------
    !> \ingroup generic_module
    !> \brief Sparse matrix to sparse matrix conversion.
    !>
    !> \details
    !> \p rocsparse_sparse_to_sparse performs the conversion of a sparse matrix to a sparse matrix.
    !>
    !> \note
    !> The required allocation size (in bytes) to \p buffer_size_in_bytes must be obtained from \ref
    !> rocsparse_sparse_to_sparse_buffer_size
    !> for each stage. The required buffer size can be different between stages.
    !>
    !> \note
    !> The \ref rocsparse_format_bell and \ref rocsparse_format_sell formats are not supported.
    !>
    !> \note
    !> This routine does not support batched computation.
    !>
    !> @param[in]
    !> handle       handle to the rocSPARSE library context queue.
    !> @param[in]
    !> descr        descriptor of the sparse_to_sparse algorithm.
    !> @param[in]
    !> source       sparse matrix descriptor.
    !> @param[in]
    !> target       sparse matrix descriptor.
    !> @param[in]
    !> stage        stage of the sparse_to_sparse computation.
    !> @param[in]
    !> buffer_size_in_bytes  size in bytes of the \p buffer.
    !> @param[in]
    !> buffer  temporary storage buffer allocated by the user.
    !>
    !> \retval      rocsparse_status_success the operation completed successfully.
    !> \par Example
    !> This example converts a CSR matrix into an ELL matrix.
    function rocsparse_sparse_to_sparse_raw(handle, descr, source, target, stage, &
                                            buffer_size_in_bytes, buffer) &
       result(sparse_to_sparse_raw) &
       bind(C, name="rocsparse_sparse_to_sparse")
       import :: c_ptr, c_int, c_long
       type(c_ptr), value :: handle
       type(c_ptr), value :: descr
       type(c_ptr), value :: source
       type(c_ptr), value :: target
       integer(c_int), value :: stage
       integer(c_long), value :: buffer_size_in_bytes
       type(c_ptr), value :: buffer
       integer(c_int) :: sparse_to_sparse_raw
    end function rocsparse_sparse_to_sparse_raw

    module procedure rocsparse_sparse_to_sparse_typed
  end interface rocsparse_sparse_to_sparse

  interface rocsparse_spgeam_buffer_size
