  interface rocsparse_zgebsrmm
    !---------------------------------------------
    ! rocsparse_zgebsrmm
    !---------------------------------------------
    function rocsparse_zgebsrmm_raw(handle, dir, trans_A, trans_B, mb, n, kb, nnzb, alpha, descr, &
                                    bsr_val, bsr_row_ptr, bsr_col_ind, row_block_dim, &
                                    col_block_dim, B, ldb, beta, C, ldc) &
       result(zgebsrmm_raw) &
       bind(C, name="rocsparse_zgebsrmm")
       import :: c_ptr, c_int, c_double_complex
       type(c_ptr), value :: handle
       integer(c_int), value :: dir
       integer(c_int), value :: trans_A
       integer(c_int), value :: trans_B
       integer(c_int), value :: mb
       integer(c_int), value :: n
       integer(c_int), value :: kb
       integer(c_int), value :: nnzb
       complex(c_double_complex) :: alpha
       type(c_ptr), value :: descr
       type(c_ptr), value :: bsr_val
       type(c_ptr), value :: bsr_row_ptr
       type(c_ptr), value :: bsr_col_ind
       integer(c_int), value :: row_block_dim
       integer(c_int), value :: col_block_dim
       type(c_ptr), value :: B
